    onBufferOverflow = BufferOverflow.SUSPEND)
launch(Dispatchers.IO) {
    val batch = ArrayList<Change>()
    while (isActive) {
        batch += changes.receive()
        while (batch.size < 100) batch += changes.tryReceive().getOrNull() ?: break
        withContext(NonCancellable) { flushInOneTransaction(batch) }
